using System;using System.IO;using System.Net;using System.Threading;
namespace ServiceTool{
internal sealed class ServiceProbeResult{internal string Message;internal bool Responded;internal int Code;}
internal static class ServiceProbe{
internal static ServiceProbeResult Check(string address,CancellationToken token,int timeout=3000){Uri uri;if(Uri.TryCreate(address,UriKind.Absolute,out uri)&&uri.Scheme=="tcp")return CheckTcp(uri,token,timeout);if(!Uri.TryCreate(address,UriKind.Absolute,out uri)||(uri.Scheme!="http"&&uri.Scheme!="https")||!uri.IsLoopback||!String.IsNullOrEmpty(uri.UserInfo))throw new ArgumentException("Укажи локальный адрес HTTP/HTTPS без имени пользователя и пароля.");var request=(HttpWebRequest)WebRequest.Create(uri);request.Method="GET";request.AllowAutoRedirect=false;request.Proxy=null;request.Timeout=request.ReadWriteTimeout=timeout;request.UserAgent="BARS-Service-Probe";using(token.Register(()=>request.Abort())){try{token.ThrowIfCancellationRequested();using(var response=(HttpWebResponse)request.GetResponse()){int code=(int)response.StatusCode;if(code==200&&uri.AbsolutePath.Equals("/Info/Ping",StringComparison.OrdinalIgnoreCase)){using(var reader=new StreamReader(response.GetResponseStream())){var buffer=new char[65];int n=reader.ReadBlock(buffer,0,buffer.Length);string pong=new string(buffer,0,n).Trim();return new ServiceProbeResult{Responded=true,Code=code,Message=(pong=="Pong"||pong==((char)34+"Pong"+(char)34))?"Служба отвечает на Ping (Pong). Оборудование и операции отдельно не проверены.":"HTTP 200 получен, но ожидаемый ответ Pong не подтверждён."};}}return Result(code);}}catch(WebException e){token.ThrowIfCancellationRequested();var response=e.Response as HttpWebResponse;if(response!=null){using(response)return Result((int)response.StatusCode);}return new ServiceProbeResult{Message=e.Status==WebExceptionStatus.Timeout?"Нет ответа за отведённое время. Зависание не подтверждено.":e.Status==WebExceptionStatus.TrustFailure||e.Status==WebExceptionStatus.SecureChannelFailure?"Не удалось проверить доверие к HTTPS-соединению. Проверь сертификат.":"Не удалось соединиться. Проверь адрес, порт и состояние службы."};}}}
internal static ServiceProbeResult CheckTcp(Uri uri,CancellationToken token,int timeout){if(!uri.IsLoopback||!String.IsNullOrEmpty(uri.UserInfo)||uri.Port<1||uri.AbsolutePath!="/"||!String.IsNullOrEmpty(uri.Query)||!String.IsNullOrEmpty(uri.Fragment))throw new ArgumentException("TCP-проверка допускает только локальный адрес и порт.");using(var client=new System.Net.Sockets.TcpClient(uri.HostNameType==UriHostNameType.IPv6?System.Net.Sockets.AddressFamily.InterNetworkV6:System.Net.Sockets.AddressFamily.InterNetwork))using(token.Register(()=>client.Close())){token.ThrowIfCancellationRequested();try{var task=client.ConnectAsync(uri.Host,uri.Port);while(!task.IsCompleted){token.ThrowIfCancellationRequested();if(timeout<=0)return new ServiceProbeResult{Message="Нет TCP-ответа за отведённое время. Зависание не подтверждено."};Thread.Sleep(Math.Min(25,timeout));timeout-=25;}task.GetAwaiter().GetResult();token.ThrowIfCancellationRequested();return new ServiceProbeResult{Responded=true,Message="Служба принимает TCP-соединение. API и оборудование не проверялись; команды не отправлялись."};}catch(Exception e){token.ThrowIfCancellationRequested();if(e is System.Net.Sockets.SocketException||e is ObjectDisposedException)return new ServiceProbeResult{Message="TCP-соединение не принято. Проверь состояние службы и её журнал."};throw;}}}
static ServiceProbeResult Result(int code){return new ServiceProbeResult{Responded=true,Code=code,Message=code>=200&&code<300?"API отвечает. Исправность оборудования и операций этим ответом не подтверждена.":code==401||code==403?"API отвечает, но для проверки требуется доступ.":code==404?"Сервер отвечает, но диагностический адрес не найден.":code==405?"HTTP-сервер отвечает, но этот адрес не принимает GET. Диагностический Ping и готовность оборудования не подтверждены.":code>=300&&code<400?"Сервер перенаправляет запрос. Уточни диагностический адрес.":"Сервер отвечает с ошибкой HTTP "+code+". Проверь собственный журнал службы."};}
}}
